23: /// Pattern: look for `Branchind` preceded by a `Load` from a computed address
24: /// that involves a base + index*scale pattern.
25: pub fn detect_switch_tables(insns: &[IrInsn]) -> Vec<SwitchTable> {
26:     let mut tables = Vec::new();
27: 
28:     for (i, insn) in insns.iter().enumerate() {
29:         if insn.op != IrOp::Branchind {
30:             continue;
31:         }
32:         // Look backwards for the load that feeds the indirect branch
33:         if i == 0 {
34:             continue;
35:         }
36:         let prev = &insns[i - 1];
37:         if prev.op == IrOp::Load {
38:             // Check if the load address computation looks like base + idx*scale
39:             if let Some(output) = &prev.output
40:                 && (output.space == SpaceId::Register || output.space == SpaceId::Unique)
41:             {
42:                 // This is a potential switch table pattern
43:                 tables.push(SwitchTable {
44:                     branch_addr: insn.addr,
45:                     table_base: 0, // Would be resolved by concrete analysis
46:                     entry_count: 0,
47:                     entry_size: output.size,
48:                     targets: Vec::new(),
49:                 });
50:             }
51:         }
52:     }
53: 
54:     tables
55: }
